 r.setdefault('source_lookup_status','EXACT_SOURCE_RECORD_PRESENT' if r.get('source_key') else 'LEGACY_ID_PRESERVED; EXACT_SOURCE_RECORD_CROSSWALK_MISSING')
 c=C.get(r['name'].strip())
 if not c:continue
 d=c['decision'];r['whole_row_adjudication']='PROJECT_LEVEL_SOURCE_REVIEWED' if d=='PROJECT_CANDIDATE_REVIEW' else ('PROJECT_IDENTITY_REVIEWED_REE_ROLE_UNRESOLVED' if d=='HOLD_REE_ROLE' else 'SOURCE_REVIEWED_HOLD_NO_CURRENT_PROJECT_EVIDENCE')
 r['definition_screen_status']=d;r['canonical_project_candidate_not_approved']=c['unit'];r['project_linkage_check']='LINKED_TO_REVIEWED_PROJECT_CANDIDATE' if d=='PROJECT_CANDIDATE_REVIEW' else ('PROJECT_IDENTITY_CONFIRMED_REE_ROLE_HOLD' if c['unit'] else 'NO_CURRENT_PROJECT_LINK_ESTABLISHED')
